cat >> tests/tasks.test.ts <<'EOF'

async function postRaw(server: Running, body: string): Promise<Response> {
  return fetch(`${server.baseUrl}/api/tasks`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body,
  });
}

async function errorOf(response: Response): Promise<{ code: string; message: string }> {
  const { error } = (await response.json()) as { error: { code: string; message: string } };
  return error;
}

describe("SL-004 reject empty and over-long titles", () => {
  let server: Running;

  before(async () => {
    server = await startServer();
  });
  after(async () => {
    await server?.stop();
  });

  it("AC-1: an empty title answers 400 validation_failed and stores nothing", async () => {
    const response = await createTask(server, "");
    assert.equal(response.status, 400);
    assert.deepEqual(await errorOf(response), {
      code: "validation_failed",
      message: "A title is required.",
    });
    assert.deepEqual(await listTasks(server), []);
  });

  it("AC-1: a title of only spaces is rejected", async () => {
    const response = await createTask(server, "   \t ");
    assert.equal(response.status, 400);
    assert.equal((await errorOf(response)).message, "A title is required.");
    assert.deepEqual(await listTasks(server), []);
  });

  it("AC-1: a missing or non-string title is rejected", async () => {
    for (const body of ["{}", '{"title":5}', '{"title":null}', "null"]) {
      const response = await postRaw(server, body);
      assert.equal(response.status, 400, body);
      assert.deepEqual(await errorOf(response), {
        code: "validation_failed",
        message: "Title must be a string.",
      });
    }
    assert.deepEqual(await listTasks(server), []);
  });

  it("AC-1: a body that is not JSON answers 400 invalid_json", async () => {
    const response = await postRaw(server, "{nope");
    assert.equal(response.status, 400);
    assert.deepEqual(await errorOf(response), {
      code: "invalid_json",
      message: "The request body is not valid JSON.",
    });
  });

  it("AC-2: a title of 501 characters is rejected and stores nothing", async () => {
    const response = await createTask(server, "a".repeat(501));
    assert.equal(response.status, 400);
    assert.deepEqual(await errorOf(response), {
      code: "validation_failed",
      message: "The title is too long (maximum 500 characters).",
    });
    assert.deepEqual(await listTasks(server), []);
  });

  it("AC-2: 500 characters are accepted, and the limit counts the trimmed title", async () => {
    const response = await createTask(server, `  ${"a".repeat(500)}  `);
    assert.equal(response.status, 201);
    const { task } = (await response.json()) as { task: Task };
    assert.equal(task.title.length, 500);
    assert.equal((await listTasks(server)).length, 1);
  });

  it("AC-1: the page shows the server's reason in the form-message alert", async () => {
    const html = await (await fetch(`${server.baseUrl}/`)).text();
    const script = await (await fetch(`${server.baseUrl}/app.js`)).text();
    assert.match(html, /<[a-z]+(?=[^>]*id=["']form-message["'])(?=[^>]*role=["']alert["'])/);
    assert.match(script, /form-message/);
    assert.match(script, /error\.message/);
    assert.doesNotMatch(script, /innerHTML/);
  });
});
EOF
